quickEquipPlan:
function quickEquipPlan(M) {
  const t = M.t(), inv = t.inventory, others = M.others(t), score = M.score;
  const def = it => it && M.def[it.itemId];
  const cur = sid => { const u = t.equipped[sid]; return u ? inv.find(i => i.uid === u) : undefined; };
  // 能穿：有定義、不是別的角色專屬、職業／性別可用、自己沒穿著、別的角色沒穿著（都是遊戲穿裝函式自己會檢查的條件）
  const usable = it => { const d = def(it); return !!d && M.mine(t, it) && M.canUse(t, d) && !M.wearing(t, it.uid) && !others.has(it.uid); };
  const cands = sid => inv.filter(it => usable(it) && M.fits(RO_EQJ(t), def(it), sid));
  const best = (list, min) => { let b = null, bs = min; for (const it of list) { const s = score(it); if (s > bs) { b = it; bs = s; } } return b; };
  const sc = it => it ? score(it) : 0;
  const plan = [], skipped = [], taken = new Set();
  const put = (sid, it) => { plan.push({ slot: sid, uid: it.uid }); taken.add(it.uid); };
  const two = it => !!it && M.twoHand(def(it));

  // 武器
  const hasW = M.slots.some(s => s.id === 'weapon'), hasS = M.slots.some(s => s.id === 'shield');
  let weapon = hasW ? cur('weapon') : undefined, shieldLocked = false;
  if (hasW) {
    const wc = cands('weapon');
    if (weapon) {
      const wt = def(weapon).wtype ?? '';
      const b = best(wc.filter(it => (def(it).wtype ?? '') === wt), sc(weapon));
      const other = best(wc.filter(it => (def(it).wtype ?? '') !== wt), Math.max(sc(weapon), sc(b)));
      if (other) skipped.push(other.uid);
      if (b) { put('weapon', b); weapon = b; }
    } else {
      // 空手：雙手武器（盾會被拿掉） vs 單手武器＋盾，取總分高的
      const one = best(wc.filter(it => !two(it)), 0), dbl = best(wc.filter(two), 0);
      const sNow = hasS ? cur('shield') : undefined;
      const sBest = hasS ? best(cands('shield').filter(it => !one || it.uid !== one.uid), sc(sNow)) : null;
      const shieldVal = Math.max(sc(sNow), sc(sBest));
      if (dbl && sc(dbl) > sc(one) + shieldVal) { put('weapon', dbl); weapon = dbl; }
      else if (one) { put('weapon', one); weapon = one; }
    }
    shieldLocked = two(weapon);
  }
  // 盾牌格（刺客可以放副手武器）
  if (hasS && !shieldLocked) {
    const sNow = cur('shield'); let sc2 = cands('shield').filter(it => !taken.has(it.uid));
    if (sNow) {
      const d0 = def(sNow);
      sc2 = sc2.filter(it => { const d = def(it); return d0.slot === 'shield' ? d.slot === 'shield' : d.slot === d0.slot && (d.wtype ?? '') === (d0.wtype ?? ''); });
    }
    const b = best(sc2, sc(sNow));
    if (b) put('shield', b);
  }
  // 其他欄位：同一種部位有幾格（飾品兩格）就挑前幾名
  const groups = new Map();
  for (const s of M.slots) { if (s.id === 'weapon' || s.id === 'shield') continue; (groups.get(s.gear) ?? groups.set(s.gear, []).get(s.gear)).push(s.id); }
  for (const sids of groups.values()) {
    const worn = sids.map(cur).filter(Boolean), wornIds = new Set(worn.map(i => i.uid));
    const pool = [...worn, ...cands(sids[0]).filter(it => !taken.has(it.uid) && !wornIds.has(it.uid))]
      .map((it, i) => ({ it, s: score(it), w: wornIds.has(it.uid) ? 0 : 1, i }))
      .sort((a, b) => b.s - a.s || a.w - b.w || a.i - b.i).slice(0, sids.length);   // 同分時現在穿著的優先（＝不換）
    const keep = new Set(pool.filter(p => !p.w).map(p => p.it.uid));
    const fresh = pool.filter(p => p.w).map(p => p.it);
    // 空出來的格子：先填空格，再換掉分數最低的
    const free = sids.filter(sid => { const c = cur(sid); return !c || !keep.has(c.uid); }).sort((a, b) => sc(cur(a)) - sc(cur(b)));
    fresh.forEach((it, k) => { if (free[k]) put(free[k], it); });
  }
  return { plan, skipped };
}

quickEquipUi:
function quickEquipUi(M, ST, planFn) {
  const E = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
  let row = document.getElementById('cp-auto');
  if (!row) {
    const work = document.querySelector('#cp-tab-equip .eq-work');
    if (!work) return;
    work.insertAdjacentHTML('beforebegin', '<div id="cp-auto"><button class="ro-btn small primary" id="cp-auto-btn">一鍵穿裝</button><span id="cp-auto-msg" class="muted"></span></div>');
    document.head.insertAdjacentHTML('beforeend', '<style>#cp-auto{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:6px 0}#cp-auto-msg{flex:1;min-width:0;font-size:var(--fs-sm,12px)}#cp-auto-msg b{color:#2a4a8a}#cp-auto-msg .warn{color:#b0562a}</style>');
    row = document.getElementById('cp-auto');
  }
  const t0 = M.t(), msg = document.getElementById('cp-auto-msg');
  msg.innerHTML = ST.msg && ST.id === t0.id ? ST.msg : '<span>幫每個欄位換上你能穿、裝備分數最高的那件（武器只在同類型裡挑）。</span>';
  document.getElementById('cp-auto-btn').onclick = () => {
    const t = M.t(), before = M.total(t), { plan, skipped } = planFn(M);
    const name = u => { const it = t.inventory.find(i => i.uid === u); return it ? E(M.name(it)) : '?'; };
    const note = skipped.length ? `<br><span class="warn">有分數更高、但武器類型不同的：${skipped.map(name).join('、')}（換類型可能讓天賦失效，請自己決定要不要手動換）</span>` : '';
    ST.id = t.id;
    if (!plan.length) { ST.msg = `目前已經是最佳裝備（裝備分數 <b>${before}</b>）。${note}`; M.redraw(); return; }
    let cards = 0, done = 0;
    for (const p of plan) {
      const old = t.equipped[p.slot], oi = old ? t.inventory.find(i => i.uid === old) : undefined;
      M.equip(t, p.uid, p.slot);                                    // 遊戲自己的穿裝函式（條件不符它自己會不動）
      if (t.equipped[p.slot] !== p.uid) continue;
      done++; if (oi) cards += (oi.cards || []).filter(Boolean).length;
      const ni = t.inventory.find(i => i.uid === p.uid); ni && delete ni.isNew;
    }
    M.sound(); M.save();                                            // 存檔（跟手動穿裝同一支），之後重畫
    const after = M.total(M.t());
    ST.msg = done ? `換上 <b>${done}</b> 件，裝備分數 <b>${before}</b> → <b>${after}</b>。` +
      (cards ? `<br><span class="warn">換下來的裝備上還有 ${cards} 張卡片（沒有自動移過去）。</span>` : '') + note
      : `沒有換到任何裝備（裝備分數 <b>${before}</b>）。${note}`;
    M.redraw();
  };
}

quickSellUi:
function quickSellUi(M, ST) {
  let box = document.getElementById('shop-quick');
  if (!box) {
    M.el('shop-quality').insertAdjacentHTML('afterend', '<div id="shop-quick" class="shop-quality"></div>');
    document.head.insertAdjacentHTML('beforeend', '<style>#shop-quick{padding:5px 6px;border:1px dashed #b9c4d8;border-radius:6px;gap:4px 10px}#shop-quick label{display:inline-flex;align-items:center;gap:3px;cursor:pointer;white-space:nowrap;font-weight:700;color:var(--q,inherit)}#shop-quick label.qs-opt{font-weight:400;color:inherit}#shop-quick label small{opacity:.7;font-weight:400}#shop-quick input{margin:0;width:16px;height:16px}#shop-quick .qs-sep{flex-basis:100%;height:0}</style>');
    box = document.getElementById('shop-quick');
  }
  if (M.cat === 'cards') { box.classList.add('hidden'); return; }
  box.classList.remove('hidden');
  const q = it => it.quality ?? 0, carded = it => (it.cards || []).some(Boolean), refined = it => (it.refine || 0) > 0;
  // 一律排除：穿著中（任何角色）、保護中、初始裝／角色專屬、不在目前分類；插卡／精煉看勾選
  const base = it => { const d = M.def[it.itemId]; return !!d && !d.starter && !it.owner && !M.worn.has(it.uid) && !it.safe && M.fit(it); };
  const elig = it => base(it) && (ST.cards || !carded(it)) && (ST.ref || !refined(it));
  const pick = () => M.inv.filter(it => elig(it) && ST.q[q(it)]);
  const sum = l => l.reduce((n, it) => n + M.price(it), 0);
  const pool = M.inv.filter(elig), cnt = M.Q.map((_, i) => pool.filter(it => q(it) === i).length);
  const all = M.inv.filter(base), nCard = all.filter(carded).length, nRef = all.filter(refined).length;
  const list = pick(), total = sum(list);
  box.innerHTML = `<span class="muted">一鍵販賣：</span>` +
    M.Q.map((Q, i) => `<label style="--q:${i ? M.qcol(i) : 'inherit'}"><input type="checkbox" data-qs="${i}"${ST.q[i] ? ' checked' : ''}> ${Q.name} <small>${cnt[i]}</small></label>`).join('') +
    `<span class="qs-sep"></span>` +
    `<label class="qs-opt"><input type="checkbox" data-qo="cards"${ST.cards ? ' checked' : ''}> 包含已插卡 <small>${nCard}</small></label>` +
    `<label class="qs-opt"><input type="checkbox" data-qo="ref"${ST.ref ? ' checked' : ''}> 包含已精煉 <small>${nRef}</small></label>` +
    `<button class="ro-btn small${list.length ? ' primary' : ''}" id="shop-quick-btn"${list.length ? '' : ' disabled'}>一鍵販賣${list.length ? `（${list.length} 件 · ${M.fmt(total)} 點）` : ''}</button>`;
  box.querySelectorAll('[data-qs]').forEach(x => { x.onchange = () => { ST.q[+x.dataset.qs] = x.checked; M.redraw(); }; });
  box.querySelectorAll('[data-qo]').forEach(x => { x.onchange = () => { ST[x.dataset.qo] = x.checked; M.redraw(); }; });
  document.getElementById('shop-quick-btn').onclick = () => {
    const l = pick(); if (!l.length) return;
    const ids = new Set(l.map(it => it.uid));
    const per = M.Q.map((Q, i) => { const n = l.filter(it => q(it) === i).length; return n ? `<b style="color:${i ? M.qcol(i) : 'inherit'}">${Q.name}</b> ×${n}` : ''; }).filter(Boolean).join('、');
    const hi = l.filter(it => q(it) >= 3).length, nc = l.filter(carded).length, nr = l.filter(refined).length;
    const html = `要一次賣掉 <b>${l.length}</b> 件裝備，換 <b>${M.fmt(sum(l))} ${M.kp}</b> 嗎？<br>${per}` +
      (hi ? `<br><span class="warn-note">注意：包含 ${hi} 件史詩／傳說裝備！</span>` : '') +
      (nc ? `<br><span class="warn-note">其中 ${nc} 件有插卡（卡片會回到卡冊）。</span>` : '') +
      (nr ? `<br><span class="warn-note">其中 ${nr} 件有精煉（精煉值不會退）。</span>` : '') +
      `<br><span class="muted">穿著中、保護中的裝備不會賣。賣掉就拿不回來。</span>`;
    M.confirm('一鍵販賣', html, '全部賣掉', () => {
      const now = pick().filter(it => ids.has(it.uid)).map(it => it.uid);   // 按下確認時再核對一次（期間存檔若被換掉，以現在的為準）
      now.length && M.sell(now);
    });
  };
}

noFlipClient:
function noFlipClient(N, C) {
  const $ = id => document.getElementById(id);
  const live = () => { const g = N.g; return g && g.state !== 'over' ? g : null; };
  let tt = 0;
  const toast = msg => {   // 小提示（用遊戲自己的 #toasts 容器，沒有就略過）
    try { const box = $('toasts'); if (!box) return; const d = document.createElement('div'); d.className = 'toast'; d.textContent = msg; box.appendChild(d); clearTimeout(tt); tt = setTimeout(() => d.remove(), 2600); } catch {}
  };
  const set = on => { const g = live(); if (!g) return; g.roNoFlip = !!on; toast(on ? C.T.toastOff : C.T.toastOn); sync(); };
  function sync() {
    const g = live(), off = !!(g && g.roNoFlip);
    const b = $('nf-btn'), p = $('picker');
    if (b) {
      const lv = !!(g && g.state === 'levelup' && !g.openingChest && p && !p.classList.contains('hidden'));   // 只在升級翻牌顯示（開寶箱也是 levelup 狀態、同一個畫面，靠 openingChest 分）
      b.classList.toggle('hidden', !lv); b.classList.toggle('on', off); b.textContent = off ? C.T.btnOn : C.T.btn;
    }
    const cb = $('nf-check'); cb && (cb.checked = !off);
  }
  function build() {
    if (!$('nf-css')) { const s = document.createElement('style'); s.id = 'nf-css'; s.textContent = C.CSS; document.head.appendChild(s); }
    const p = $('picker');
    if (p && !$('nf-btn')) {
      const b = document.createElement('button'); b.id = 'nf-btn'; b.className = 'ro-btn small hidden'; b.type = 'button';
      b.addEventListener('pointerdown', e => e.stopPropagation());
      b.addEventListener('click', e => { e.stopPropagation(); set(true); });
      (p.querySelector('.pk-inner') || p).appendChild(b);
    }
    const pb = document.querySelector('#pause .ro-body');
    if (pb && !$('nf-pause')) {
      pb.insertAdjacentHTML('beforeend', `<div id="nf-pause"><label class="opt-row opt-check"><span><b>${C.T.row}</b><small>${C.T.rowHint}</small></span><input type="checkbox" id="nf-check" checked><i class="opt-switch"></i></label></div>`);
      $('nf-check').addEventListener('change', e => set(!e.target.checked));
    }
    sync();
  }
  // 翻牌畫面、暫停選單出現時同步（官方是切 hidden class）
  const watch = () => {
    build();
    for (const id of ['picker', 'pause']) { const el = $(id); el && !el.dataset.nfObs && (el.dataset.nfObs = '1', new MutationObserver(() => { build(); }).observe(el, { attributes: true, attributeFilter: ['class'] })); }
  };
  document.readyState === 'loading' ? document.addEventListener('DOMContentLoaded', watch) : watch();
  setInterval(watch, 3000);   // 遊戲重建 HUD／換場景後補掛（很輕：元素都在就只同步狀態）
}
